const yz_book_info_t YZ_BOOK = {
    "多宝塔碑", "多\n宝\n塔\n碑", "唐天宝十一载（752）", "唐 · 颜真卿 书",
    "碑文",
    "全称《大唐西京千福寺\n多宝佛塔感应碑》。\n唐天宝十一载（752）立，\n岑勋撰文，颜真卿书丹，\n徐浩题额，今藏西安碑林。\n\n颜真卿时年四十四岁，\n结字严密，端庄秀丽，\n是初学颜体的经典范本。\n\n全碑 2025 字分作九卷，\n可按碑文顺序逐字通临。",
    "《多宝塔碑》高清剪裱本，\n共 42 页，每页五行、\n行十字（个别页例外）。\n\n全碑 2025 字逐字裁切，\n含偈颂后“其一”至\n“其七”小字；保留石花\n与笔意，未作描修。\n\n释文据维基文库校对，\n异体字以通行繁体标注。",
};

